use verus::prelude::*;

verus! {

    /// Spec‐level function counting `true` in mask[0..i].
    #[verifier::spec]
    fn count_true(mask: &Vec<bool>, i: nat) -> nat {
        if i == 0 {
            0
        } else {
            count_true(mask, i - 1)
                + (if mask[(i - 1) as usize] { 1 } else { 0 })
        }
    }

    /// place replaces each `arr[i]` where `mask[i]` is true by the next
    /// value from `vals`, cycling through `vals`.  Wherever `mask[i]` is false,
    /// we keep the original `arr[i]`.
    fn place(arr: Vec<f32>, mask: Vec<bool>, vals: Vec<f32>) -> (result: Vec<f32>)
        requires arr.len() == mask.len(),
        requires vals.len() > 0,
        ensures  result.len() == arr.len(),
        ensures  forall |i: usize| i < arr.len() ==>
                    if !mask[i] {
                        result[i] == arr[i]
                    } else {
                        let k: usize = count_true(&mask, i);
                        result[i] == vals[k % vals.len()]
                    },
    {
        let n = arr.len();
        // We'll build result incrementally.
        let mut result: Vec<f32> = Vec::new();
        let mut i: usize = 0;
        // rep_count = number of times we've seen mask[j]==true for j<i
        let mut rep_count: usize = 0;

        while i < n
            invariant i <= n,
            invariant rep_count <= i,
            invariant result.len() == i,
            invariant forall |j: usize| j < i ==>
                if !mask[j] {
                    result[j] == arr[j]
                } else {
                    let ct: usize = count_true(&mask, j);
                    result[j] == vals[ct % vals.len()]
                },
            decreases n - i,
        {
            if !mask[i] {
                // no replacement: copy original
                result.push(arr[i]);
            } else {
                // replacement: pick next vals, update rep_count
                result.push(vals[rep_count % vals.len()]);
                rep_count = rep_count + 1;
            }
            i = i + 1;
        }
        result
    }

}